const labels = {
  MODEL_OUTPUT_INVALID_JSON: 'a leitura da IA não retornou dados válidos',
  DOCUMENT_EXTRACTION_EMPTY: 'não foi possível ler o conteúdo do arquivo',
  OCR_LOW_CONFIDENCE: 'a imagem está pouco legível',
  LOW_CONFIDENCE: 'a classificação precisa de conferência',
  MISSING_REFERENCE_DATE: 'data do documento não identificada; foi usada a data de recebimento para arquivar',
  UNKNOWN_DOCUMENT_TYPE: 'tipo do documento não identificado',
  DOCUMENT_TYPE_NOT_EVIDENCED: 'tipo do documento sem evidência legível',
  CLIENT_COMPANY_NOT_EVIDENCED: 'empresa atendida não localizada no documento',
  DEPARTMENT_REQUIRES_REVIEW: 'departamento precisa de conferência',
  FISCAL_ISSUE_DATE_NOT_EVIDENCED: 'data de emissão não identificada',
  FISCAL_TOTAL_AMOUNT_NOT_EVIDENCED: 'valor total da nota não identificado',
  FISCAL_ISSUER_NOT_EVIDENCED: 'emitente da nota não identificado',
  FISCAL_DOCUMENT_NUMBER_NOT_EVIDENCED: 'número do documento fiscal não identificado',
  ISSUER_NOT_EVIDENCED: 'emissor/beneficiário não identificado',
  RECIPIENT_NOT_EVIDENCED: 'destinatário/pagador não identificado',
  PAYMENT_DUE_DATE_NOT_EVIDENCED: 'data de vencimento não identificada',
  PAYMENT_AMOUNT_NOT_EVIDENCED: 'valor do documento de pagamento não identificado',
  PAYMENT_BENEFICIARY_NOT_EVIDENCED: 'beneficiário não identificado',
  PAYMENT_CODE_NOT_EVIDENCED: 'linha digitável ou código de barras não identificado'
};
const rows = $input.all().map(i => i.json);
const groupId = '{{WHATSAPP_GROUP_ID}}@g.us';
const fmtDate = (value) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value));
const day = fmtDate(new Date());
const typeLabels = {
  'nf-e':'NF-e','nfs-e':'NFS-e','nfc-e':'NFC-e','cupom-fiscal':'Cupom fiscal','ct-e':'CT-e','mdf-e':'MDF-e',
  extrato:'Extrato',comprovante:'Comprovante',recibo:'Recibo',boleto:'Boleto',fatura:'Fatura',balancete:'Balancete',
  razao:'Razão',diario:'Diário',dre:'DRE',folha:'Folha',holerite:'Holerite',fgts:'FGTS',inss:'INSS',guia:'Guia',outro:'Outro'
};
const departmentLabels = { fiscal:'Fiscal', financeiro:'Financeiro', contabil:'Contábil', pessoal:'Pessoal', revisar:'Revisar' };
const today = rows.filter(r => ['ORGANIZED','ORGANIZED_ATTENTION'].includes(r.status) && r.group_id === groupId && r.organized_at && fmtDate(r.organized_at) === day);
const byType = today.reduce((acc, row) => { const key = typeLabels[String(row.document_type ?? 'outro').toLowerCase()] ?? 'Outro'; acc[key] = (acc[key] ?? 0) + 1; return acc; }, {});
const byDepartment = today.reduce((acc, row) => { const key = departmentLabels[String(row.department ?? 'revisar').toLowerCase()] ?? 'Revisar'; acc[key] = (acc[key] ?? 0) + 1; return acc; }, {});
const pending = today.filter(row => row.review_required || row.status === 'ORGANIZED_ATTENTION');
const typeLines = Object.entries(byType).sort((a,b) => b[1]-a[1]).map(([name,count]) => '• ' + name + ': ' + count).join('\n');
const departmentLines = Object.entries(byDepartment).sort((a,b) => b[1]-a[1]).map(([name,count]) => '• ' + name + ': ' + count).join('\n');
const observationLines = pending.slice(0, 20).map(row => {
  const reasons = String(row.review_reason ?? '').split('|').filter(Boolean).map(reason => labels[reason] ?? reason);
  return '• ' + (row.organized_filename || row.original_filename || 'arquivo sem nome') + ': ' + (reasons.join('; ') || 'conferência manual');
}).join('\n');
const report = [
  '📋 Fechamento diário da triagem — ' + day,
  '',
  '• Documentos armazenados: ' + today.length,
  '• Sem pendência: ' + (today.length - pending.length),
  '• Precisam de atenção: ' + pending.length,
  '',
  typeLines ? 'Categorias:\n' + typeLines : 'Nenhum documento foi organizado hoje.',
  departmentLines ? '\nDepartamentos:\n' + departmentLines : '',
  observationLines ? '\nObservações:\n' + observationLines : '\nObservações: nenhuma pendência registrada.',
  pending.length > 20 ? '• Há mais ' + (pending.length - 20) + ' pendência(s) no CSV detalhado.' : '',
  '',
  'O CSV detalhado foi arquivado em 02 - FECHAMENTOS.'
].filter(Boolean).join('\n');
const base = {
  report_date: day, total_day: today.length, pending_count: pending.length,
  group_id: groupId, summary_text: report, generated_at: new Date().toISOString()
};
if (!today.length) return [{ json: { ...base, status: 'NO_DOCUMENTS', received_at: '', document_type: '', department: '', organized_filename: '', organized_path: '', review_required: false, review_reason: '' } }];
return today.map(row => ({ json: {
  ...base, status: 'CLOSED', received_at: row.received_at,
  document_type: row.document_type, department: row.department,
  issuer_name: row.issuer_name, recipient_name: row.recipient_name,
  organized_filename: row.organized_filename, organized_path: row.organized_path,
  drive_url: row.drive_web_url, review_required: Boolean(row.review_required),
  review_reason: row.review_reason ?? '', processing_status: row.status
} }));
